content.content:
1	"use client";
2	
3	/**
4	 * Client-side plumbing for feature flags.
5	 *
6	 * The server evaluates every flag once per request with `snapshotFlags()` and
7	 * serialises the result into `FeatureFlagProvider`. The client therefore reads
8	 * the snapshot rather than re-deriving anything — but when a key is missing
9	 * (a snapshot serialised before a newly shipped flag existed) we fall back to
10	 * `isEnabled()` so there is still exactly one evaluator in the codebase.
11	 */
12	import { createContext } from "react";
13	import { isEnabled } from "@/lib/feature-flags";
14	import type {
15	  FeatureFlagKey,
16	  FeatureFlagSnapshot,
17	  FlagContext,
18	} from "@/types/feature-flag";
19	import type { Actor } from "@/types/member";
20	import type { Organization } from "@/types/organization";
21	
22	/** Context for a signed-out / pre-hydration reader: free plan, no role. */
23	export const ANONYMOUS_FLAG_CONTEXT: FlagContext = {
24	  orgId: null,
25	  userId: null,
26	  plan: "free",
27	  role: null,
28	};
29	
30	/** The full evaluation context for a member browsing one organization. */
31	export function orgFlagContext(org: Organization, actor: Actor): FlagContext {
32	  return {
33	    orgId: org.id,
34	    userId: actor.userId,
35	    plan: org.plan,
36	    role: actor.role,
37	    overrides: org.settings.enabledFlagOverrides,
38	  };
39	}
