30	
31	export type NotificationPreferencesFormProps = {
32	  orgId: OrgId;
33	  userId: UserId;
34	  preferences: readonly NotificationPreference[];
35	  flags: FeatureFlagSnapshot;
36	  onSubmit: (
37	    input: UpdateNotificationPreferenceInput,
38	  ) => Promise<ActionResult<NotificationPreference>>;
39	};
40	
41	const KIND_LABELS: Readonly<Record<NotificationKind, string>> = {
42	  issue_assigned: "Issue assigned to me",
43	  issue_status_changed: "Issue status changed",
44	  issue_due_soon: "Issue due soon",
45	  issue_overdue: "Issue overdue",
46	  comment_created: "New comment",
47	  comment_mention: "I was mentioned",
48	  member_invited: "Member invited",
49	  member_joined: "Member joined",
50	  project_archived: "Project archived",
51	  plan_limit_reached: "Plan limit reached",
52	  digest_ready: "Daily digest ready",
53	};
54	
55	export function NotificationPreferencesForm(
56	  props: NotificationPreferencesFormProps,
57	): ReactElement | null {
58	  const { orgId, userId, preferences, flags, onSubmit } = props;
59	  const { submit, pending } = useFormAction(onSubmit);
60	
61	  const digestOn =
62	    flags.digest_email === true ||
63	    isEnabled("digest_email", ANONYMOUS_FLAG_CONTEXT);
64	
65	  function update(
66	    preference: NotificationPreference,
67	    patch: Partial<
68	      Pick<NotificationPreference, "inApp" | "email" | "digestOnly">
69	    >,
70	  ): void {
71	    void submit({
72	      orgId,
73	      userId,
74	      kind: preference.kind,
75	      inApp: patch.inApp ?? preference.inApp,
76	      email: patch.email ?? preference.email,
77	      digestOnly: patch.digestOnly ?? preference.digestOnly,
78	    });
79	  }
80	
81	  return (
82	    <Table caption="Notification preferences">
83	      <TableHead>
84	        <TableRow>
85	          <TableHeaderCell>Event</TableHeaderCell>
86	          <TableHeaderCell>In app</TableHeaderCell>
87	          <TableHeaderCell>Email</TableHeaderCell>
88	          {digestOn ? <TableHeaderCell>Digest only</TableHeaderCell> : null}
89	        </TableRow>
90	      </TableHead>
91	
92	      <TableBody>
93	        {preferences.map((preference) => (
94	          <TableRow key={preference.kind}>
95	            <TableCell>{KIND_LABELS[preference.kind]}</TableCell>
96	
97	            <TableCell className="w-24">
98	              <Switch
99	                name={`${preference.kind}-in-app`}
100	                checked={preference.inApp}
101	                disabled={pending}
102	                onChange={(checked) => update(preference, { inApp: checked })}
103	              />
104	            </TableCell>
105	
106	            <TableCell className="w-24">
107	              <Switch
108	                name={`${preference.kind}-email`}
109	                checked={preference.email}
110	                disabled={pending}
111	                onChange={(checked) => update(preference, { email: checked })}
112	              />
113	            </TableCell>
114	
115	            {digestOn ? (
116	              <TableCell className="w-28">
117	                <Switch
118	                  name={`${preference.kind}-digest`}
119	                  checked={preference.digestOnly}
120	                  // Batching only makes sense when email is on at all.
121	                  disabled={pending || !preference.email}
122	                  onChange={(checked) =>
123	                    update(preference, { digestOnly: checked })
124	                  }
125	                />
